const s=wb.getWorksheet('Sheet1');
for(let r=16;r<=37;r++){ s.getRange('Q'+r).setValue(`=(+D${r}*70)+(E${r}*69)+(F${r}*64)+(G${r}*61)+(H${r}*58)+(I${r}*57)+(J${r}*52)+(K${r}*46)+(L${r}*45)+(M${r}*34)+(N${r}*22)+(O${r}*10)+(P${r}*4)`); }
s.getRange('Q38').setValue('=SUM(Q3:Q37)');
s.getRange('Q3:Q38').getStyle().getFont().setBold(false);
log(s.getRange('Q2:Q38'));
const q=['Q3','Q15','Q16','Q17','Q36','Q37','Q38'].map(a=>{const c=s.getRange(a).getCell();return a+' | '+c.getValue()+' | '+c.getText()+' | bold='+c.getStyle().getFont().getBold()+' | '+c.getFormula()});
log(q.join('\n'));
log('check via headers', await wb.evaluate('=SUMPRODUCT(Sheet1!D3:P37*(81-(VALUE(SUBSTITUTE(Sheet1!D2:P2,"Month ",""))-1)))'));
log('check via row 38', await wb.evaluate('=SUMPRODUCT(Sheet1!D38:P38,{70,69,64,61,58,57,52,46,45,34,22,10,4})'));
log('Q36 check', await wb.evaluate('=SUMPRODUCT(Sheet1!D36:P36*(82-VALUE(MID(Sheet1!D2:P2,7,3))))'));
log(s.getRange('Q3:Q38').getCounts());

